                "sampleValue": "距离锁屏还有15分钟"
              },
              "dtStart": {
                "type": "string",
                "description": "限制开始时间",
                "sampleValue": "21:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "限制结束时间",
                "sampleValue": "21:15"
              },
              "entityId": {
                "type": "string",
                "description": "日历限制项唯一标识",
                "sampleValue": "calendar-limit-video"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/clock_fill.svg",
      "description": "时钟实心图标，适合作为倒计时、时间限制和闹钟设置的主视觉。"
    }
  ]
}

